struct vector3d {
    float x, y, z;
};

struct po {
    char pad0[32];
    vector3d position;
    char pad1[4];
    vector3d facing;
};

struct entity {
    char pad[80];
    po* my_abs_po;
};

extern float* fast_acos_lookup_table;

static inline float fast_acos(float x) {
    return fast_acos_lookup_table[(int)((x + 1.0f) * 8192.0f)];
}

static inline float xz_rotation(float x, float z) {
    float result = 0.0f;
    if (x != 0.0f || z != 0.0f) {
        result = fast_acos(z / __builtin_sqrtf(z * z + x * x));
        if (x < 0.0f)
            result = -result;
    }
    return result;
}

class ai_locomotion {
public:
    entity* get_my_entity() const __asm__("get_my_entity__C13ai_locomotion");
    float get_xz_rotation_to_point(const vector3d& point) const;
};

float ai_locomotion::get_xz_rotation_to_point(const vector3d& point) const {
    vector3d facing = get_my_entity()->my_abs_po->position;
    vector3d delta;
    po* abs_po = get_my_entity()->my_abs_po;
    delta.x = point.x - abs_po->facing.x;
    delta.y = point.y - abs_po->facing.y;
    delta.z = point.z - abs_po->facing.z;
    float target_rotation = xz_rotation(-delta.x, delta.z);
    float current_rotation = xz_rotation(-facing.x, facing.z);
    float result = target_rotation - current_rotation;
    if (result > 3.1415927f)
        result -= 6.2831855f;
    if (result < -3.1415927f)
        result += 6.2831855f;
    return result;
}
